{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The glass diver arrives at the ruined royal city.",
      "visual_description": "A shattered gateway with rusted iron hinges, broken royal banners hanging limp, and the glass diver standing at the threshold, his helmet reflecting the collapsed towers beyond.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "Mara the cartographer unfolds a map of the city.",
      "visual_description": "Mara kneels on a fallen stone, spreading a cracked parchment map weighted with a brass compass, her ink-stained fingers tracing a path through the ruins.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp warns of a cursed tower.",
      "visual_description": "Inside a crumbling courtyard, the oracle lamp flickers on a pedestal, its single eye of flame widening as it casts a smoky image of a twisted tower with thrumming magic doors.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "The sleeping tax collector blocks a passage.",
      "visual_description": "A narrow alley choked with rubble, the sleeping tax collector slumped against a wall, using a ledger book as a pillow, stamped papers fluttering from his sleeves.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 5,
      "caption": "Tin fox scouts ahead among fallen banners.",
      "visual_description": "The small metal fox picks its way through heaps of torn royal banners, its blue glass eyes scanning, its key-wind tail ticking softly.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "The glass diver swims through a mirrored window.",
      "visual_description": "The glass diver presses his helmet against a cracked windowpane, then steps through as if diving, emerging into a dark hall on the other side.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "Mara marks a safe route past armored patrols.",
      "visual_description": "Mara peers around a broken column at a distant patrol of faceless armored figures, quickly inking an alternate path on her map.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 8,
      "caption": "The oracle lamp reveals a trap inside a magic door.",
      "visual_description": "The lamp's flame projects a ghostly image of a glowing magic door, with hidden spikes waiting beyond the threshold.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "Tin fox triggers a false floor and escapes.",
      "visual_description": "The tin fox steps on a loose stone, a trapdoor opens beneath it, but it springs away using its metal tail as a counterbalance.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "The sleeping tax collector is dragged to safety.",
      "visual_description": "Mara and the glass diver each take an arm of the dozing tax collector, hauling him through a narrow archway as rubble falls behind them.",
      "characters": ["mara_the_cartographer", "glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 11,
      "caption": "The glass diver finds a hidden passage through a mirror.",
      "visual_description": "In a shattered hall of mirrors, the glass diver taps a specific reflection, which ripples and opens into a secret corridor.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "Mara reads a faded inscription on a weathered wall.",
      "visual_description": "Mara brushes moss from a stone plaque, her compass needle spinning as she deciphers an old warning about the bridge ahead.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "The oracle lamp warns of falling debris.",
      "visual_description": "The lamp's flame pulses red, and a moment later a chunk of cornice crashes where the group had been standing.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 14,
      "caption": "Tin fox leads them past a cursed tower's shadow.",
      "visual_description": "The fox's blue eyes glow as it guides the group along the base of the cursed tower, its shadow stretching unnaturally under a strange light.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "The glass diver creates a mirror bridge over a chasm.",
      "visual_description": "The glass diver shatters a large mirror and arranges the shards to form a reflective walkway across a deep fissure in the city floor.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "The sleeping tax collector briefly wakes to point at a door.",
      "visual_description": "Bleary-eyed, the tax collector lifts a stamped paper and gestures weakly at a hidden door behind a tapestry, then dozes off again.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "The group reaches the final bridge.",
      "visual_description": "A long stone bridge spans a dry riverbed, broken royal banners on both sides, the exit gate visible at the far end.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "They cross the bridge and escape the ruined city.",
      "visual_description": "The five figures hurry across the bridge, the city's cursed towers crumbling behind them, as the glass diver's helmet reflects the open sky ahead.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    }
  ]
}

